package gov.takx.api.emergency;

import gov.tak.api.maps.PointMapItem;
import jakarta.annotation.Nonnull;
import jakarta.annotation.Nullable;

/**
 * Describes an alert generated by the receipt of an Emergency Alert CoT message.
 *
 * @param mapItem Map item representing the alert
 * @param callsign Callsign for the map item
 * @param type Alert type, like "911"
 * @param message Alert message (optional)
 * @since 5.7
 */
public record EmergencyAlert(@Nonnull PointMapItem mapItem, @Nonnull String callsign, @Nonnull String type, @Nullable String message)
{
}
